:root {
  --bg: #2d1b2e;
  --card: #3e2a3f;
  --text: #f0e6d2;
  --accent: #e6a817;
  --accent-dark: #b8860b;
  --danger: #d9534f;
  --border: #5a3e5b;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: var(--bg);
  background-image: radial-gradient(circle, var(--border) 1px, transparent 1px);
  background-size: 20px 20px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}
h1 {
  font-size: 28px;
  text-align: center;
  margin-bottom: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--accent-dark);
}
.input-group {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  font-size: 18px;
  font-family: inherit;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  outline: none;
  min-width: 0;
}
input[type="text"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(230,168,23,0.3);
}
button {
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  padding: 10px 18px;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--accent-dark);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: transform 0.05s, background 0.1s;
}
button:hover { background: #f0c040; }
button:active { transform: translate(2px, 2px); }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.counts {
  display: flex;
  justify-content: space-between;
  font-size: 16px;
  margin-bottom: 16px;
  padding: 8px 12px;
  background: var(--bg);
  border: 2px solid var(--border);
}
#todo-list { list-style: none; }
#todo-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  margin-bottom: 8px;
  background: var(--bg);
  border: 2px solid var(--border);
}
#todo-list li.done span { text-decoration: line-through; opacity: 0.6; }
#todo-list input[type="checkbox"] {
  width: 22px;
  height: 22px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
#todo-list span {
  flex: 1;
  word-break: break-word;
}
#todo-list button {
  padding: 4px 10px;
  font-size: 16px;
  background: var(--danger);
  border-color: #a33;
}
#todo-list button:hover { background: #e06060; }
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 22px; }
  .input-group { flex-direction: column; }
  button#todo-add { width: 100%; }
}

let nextId = 1;
const tasks = [];

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const id = nextId++;
  const task = { id, text, done: false };
  tasks.push(task);

  const li = document.createElement('li');
  li.id = 'todo-item-' + id;

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'todo-check-' + id;
  checkbox.setAttribute('aria-label', 'Mark "' + text + '" as complete');
  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    li.classList.toggle('done', task.done);
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = 'todo-text-' + id;
  span.textContent = text;

  const del = document.createElement('button');
  del.id = 'todo-delete-' + id;
  del.textContent = '✕';
  del.setAttribute('aria-label', 'Delete "' + text + '"');
  del.addEventListener('click', () => {
    const idx = tasks.indexOf(task);
    if (idx > -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, del);
  list.appendChild(li);
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
